(x, y, t) => {
  const s1x = 160 + Math.sin(t * 0.6) * 100, s1y = 80 + Math.cos(t * 0.4) * 50;
  const s2x = 320 + Math.cos(t * 0.5) * 100, s2y = 160 + Math.sin(t * 0.7) * 50;
  const s3x = 240 + Math.sin(t * 0.3 + 2) * 140, s3y = 120 + Math.cos(t * 0.5 + 1) * 90;
  const d1 = Math.sqrt((x - s1x) ** 2 + (y - s1y) ** 2);
  const d2 = Math.sqrt((x - s2x) ** 2 + (y - s2y) ** 2);
  const d3 = Math.sqrt((x - s3x) ** 2 + (y - s3y) ** 2);
  const w1 = Math.sin(d1 * 0.08 - t * 2), w2 = Math.sin(d2 * 0.1 - t * 1.7), w3 = Math.sin(d3 * 0.06 - t * 2.3);
  const w4 = Math.sin(x * 0.05 + y * 0.03 + t * 0.8), w5 = Math.sin(x * 0.03 - y * 0.05 + t * 1.1);
  const w6 = Math.sin((x + y) * 0.15 + t * 3) * 0.15, w7 = Math.sin((x - y) * 0.12 - t * 2.5) * 0.15;
  const activator = (w1 + w2 + w3) / 3, inhibitor = (w4 + w5) / 2;
  const reaction = activator - inhibitor * 0.8 + w6 + w7;
  const spot = Math.tanh(reaction * 2.5);
  const cx = 240, cy = 120, dist = Math.sqrt((x - cx) ** 2 + (y - cy) ** 2);
  const ang = Math.atan2(y - cy, x - cx);
  const radial = Math.sin(dist * 0.04 - t * 1.5), angular = Math.sin(ang * 6 + t * 0.4);
  const pattern2 = Math.tanh((radial + angular * 0.5) * 2);
  const blend = spot * 0.6 + pattern2 * 0.4;
  const v = blend * 0.5 + 0.5;
  const pal = [[12,20,72],[18,105,128],[210,175,45],[195,75,55],[12,20,72]];
  const idx = v * (pal.length - 1), i = Math.min(idx | 0, pal.length - 2), f = idx - i;
  const lum = 0.85 + Math.sin(reaction * Math.PI) * 0.15;
  return [
    Math.min(255, (pal[i][0] + (pal[i+1][0] - pal[i][0]) * f) * lum) | 0,
    Math.min(255, (pal[i][1] + (pal[i+1][1] - pal[i][1]) * f) * lum) | 0,
    Math.min(255, (pal[i][2] + (pal[i+1][2] - pal[i][2]) * f) * lum) | 0
  ];
}
